#if defined(LGFXVIRTUALCANVAS_H)
using Canvas = LGFXVirtualCanvas;
#else
using Canvas = lgfx::LGFXBase;
#endif

class Screen : public lgfxsb::RendererT<Canvas> {
  using Base = lgfxsb::RendererT<Canvas>;
  void (*_ov_Boot)(Canvas&, const Scene::Boot&) = nullptr;
  static void _ovt_Boot(Canvas& g, const void* s, const void* fnp) { (*static_cast<void (*const*)(Canvas&, const Scene::Boot&)>(fnp))(g, *static_cast<const Scene::Boot*>(s)); }
  void (*_ov_Drive)(Canvas&, const Scene::Drive&) = nullptr;
  static void _ovt_Drive(Canvas& g, const void* s, const void* fnp) { (*static_cast<void (*const*)(Canvas&, const Scene::Drive&)>(fnp))(g, *static_cast<const Scene::Drive*>(s)); }
  void (*_ov_TrainSelect)(Canvas&, const Scene::TrainSelect&) = nullptr;
  static void _ovt_TrainSelect(Canvas& g, const void* s, const void* fnp) { (*static_cast<void (*const*)(Canvas&, const Scene::TrainSelect&)>(fnp))(g, *static_cast<const Scene::TrainSelect*>(s)); }
  void (*_ov_Settings)(Canvas&, const Scene::Settings&) = nullptr;
  static void _ovt_Settings(Canvas& g, const void* s, const void* fnp) { (*static_cast<void (*const*)(Canvas&, const Scene::Settings&)>(fnp))(g, *static_cast<const Scene::Settings*>(s)); }
  void (*_ov_Message)(Canvas&, const Scene::Message&) = nullptr;
  static void _ovt_Message(Canvas& g, const void* s, const void* fnp) { (*static_cast<void (*const*)(Canvas&, const Scene::Message&)>(fnp))(g, *static_cast<const Scene::Message*>(s)); }
 public:
  explicit Screen(lgfx::LGFX_Device& gfx) : Base(gfx, project) {}
  void setProfile(Profile p) { _profile = static_cast<uint8_t>(p); }
  void show(lgfxsb::SceneId id) { renderScene(id, nullptr, 0); }
  void show(const Scene::Boot& s) {
    lgfxsb::Value v[3];
    if (s.title) v[1] = lgfxsb::Value::text(s.title);
    if (s.status) v[2] = lgfxsb::Value::text(s.status);
    renderScene(Scene::Boot::id, v, 3, _ov_Boot ? &_ovt_Boot : nullptr, &s, &_ov_Boot);
  }
  void setOverlay(void (*fn)(Canvas&, const Scene::Boot&)) { _ov_Boot = fn; }
  void show(const Scene::Drive& s) {
    lgfxsb::Value v[38];
    if (s.trainName) v[1] = lgfxsb::Value::text(s.trainName);
    if (s.sensorStatus) v[2] = lgfxsb::Value::text(s.sensorStatus);
    if (s.stateText) v[4] = lgfxsb::Value::text(s.stateText);
    v[8].visible = s.trainBtnPressedVisible.v;
    if (s.trainBtnLabel) v[9] = lgfxsb::Value::text(s.trainBtnLabel);
    v[12].visible = s.stopBtnPressedVisible.v;
    if (s.stopBtnLabel) v[13] = lgfxsb::Value::text(s.stopBtnLabel);
    v[16].visible = s.fx1PressedVisible.v;
    if (s.fx1Label) v[17] = lgfxsb::Value::text(s.fx1Label);
    v[20].visible = s.fx2PressedVisible.v;
    if (s.fx2Label) v[21] = lgfxsb::Value::text(s.fx2Label);
    v[24].visible = s.fx3PressedVisible.v;
    if (s.fx3Label) v[25] = lgfxsb::Value::text(s.fx3Label);
    v[28].visible = s.fx4PressedVisible.v;
    if (s.fx4Label) v[29] = lgfxsb::Value::text(s.fx4Label);
    v[32].visible = s.fx5PressedVisible.v;
    if (s.fx5Label) v[33] = lgfxsb::Value::text(s.fx5Label);
    v[36].visible = s.fx6PressedVisible.v;
    if (s.fx6Label) v[37] = lgfxsb::Value::text(s.fx6Label);
    renderScene(Scene::Drive::id, v, 38, _ov_Drive ? &_ovt_Drive : nullptr, &s, &_ov_Drive);
  }
  void setOverlay(void (*fn)(Canvas&, const Scene::Drive&)) { _ov_Drive = fn; }
  Scene::Drive::Part hitTest(const Scene::Drive& s, int32_t x, int32_t y) {
    static const uint16_t t[] = {0, 5, 7, 11, 15, 19, 23, 27, 31, 35};
    lgfxsb::Value v[38];
    v[8].visible = s.trainBtnPressedVisible.v;
    v[12].visible = s.stopBtnPressedVisible.v;
    v[16].visible = s.fx1PressedVisible.v;
    v[20].visible = s.fx2PressedVisible.v;
    v[24].visible = s.fx3PressedVisible.v;
    v[28].visible = s.fx4PressedVisible.v;
    v[32].visible = s.fx5PressedVisible.v;
    v[36].visible = s.fx6PressedVisible.v;
    return static_cast<Scene::Drive::Part>(hitTestScene(Scene::Drive::id, v, 38, t, 10, x, y));
  }
  bool bounds(Scene::Drive::Part p, lgfxsb::Rect& out) { return partBounds(Scene::Drive::id, static_cast<uint16_t>(p), out); }
  void show(const Scene::TrainSelect& s) {
    lgfxsb::Value v[30];
    v[3].visible = s.backBtnPressedVisible.v;
    if (s.backBtnLabel) v[4] = lgfxsb::Value::text(s.backBtnLabel);
    if (s.title) v[5] = lgfxsb::Value::text(s.title);
    v[7].visible = s.card1Visible.v;
    v[8].visible = s.card1SelectedVisible.v;
    if (s.card1Name) v[9] = lgfxsb::Value::text(s.card1Name);
    v[11].visible = s.card2Visible.v;
    v[12].visible = s.card2SelectedVisible.v;
    if (s.card2Name) v[13] = lgfxsb::Value::text(s.card2Name);
    v[15].visible = s.card3Visible.v;
    v[16].visible = s.card3SelectedVisible.v;
    if (s.card3Name) v[17] = lgfxsb::Value::text(s.card3Name);
    v[19].visible = s.card4Visible.v;
    v[20].visible = s.card4SelectedVisible.v;
    if (s.card4Name) v[21] = lgfxsb::Value::text(s.card4Name);
    v[23].visible = s.card5Visible.v;
    v[24].visible = s.card5SelectedVisible.v;
    if (s.card5Name) v[25] = lgfxsb::Value::text(s.card5Name);
    v[27].visible = s.card6Visible.v;
    v[28].visible = s.card6SelectedVisible.v;
    if (s.card6Name) v[29] = lgfxsb::Value::text(s.card6Name);
    renderScene(Scene::TrainSelect::id, v, 30, _ov_TrainSelect ? &_ovt_TrainSelect : nullptr, &s, &_ov_TrainSelect);
  }
  void setOverlay(void (*fn)(Canvas&, const Scene::TrainSelect&)) { _ov_TrainSelect = fn; }
  Scene::TrainSelect::Part hitTest(const Scene::TrainSelect& s, int32_t x, int32_t y) {
    static const uint16_t t[] = {2, 7, 11, 15, 19, 23, 27};
    lgfxsb::Value v[30];
    v[3].visible = s.backBtnPressedVisible.v;
    v[7].visible = s.card1Visible.v;
    v[8].visible = s.card1SelectedVisible.v;
    v[11].visible = s.card2Visible.v;
    v[12].visible = s.card2SelectedVisible.v;
    v[15].visible = s.card3Visible.v;
    v[16].visible = s.card3SelectedVisible.v;
    v[19].visible = s.card4Visible.v;
    v[20].visible = s.card4SelectedVisible.v;
    v[23].visible = s.card5Visible.v;
    v[24].visible = s.card5SelectedVisible.v;
    v[27].visible = s.card6Visible.v;
    v[28].visible = s.card6SelectedVisible.v;
    return static_cast<Scene::TrainSelect::Part>(hitTestScene(Scene::TrainSelect::id, v, 30, t, 7, x, y));
  }
  bool bounds(Scene::TrainSelect::Part p, lgfxsb::Rect& out) { return partBounds(Scene::TrainSelect::id, static_cast<uint16_t>(p), out); }
  void show(const Scene::Settings& s) {
    lgfxsb::Value v[32];
    v[3].visible = s.backBtnPressedVisible.v;
    if (s.backBtnLabel) v[4] = lgfxsb::Value::text(s.backBtnLabel);
    if (s.title) v[5] = lgfxsb::Value::text(s.title);
    if (s.volLabel) v[6] = lgfxsb::Value::text(s.volLabel);
    v[9].visible = s.volDownPressedVisible.v;
    if (s.volDownLabel) v[10] = lgfxsb::Value::text(s.volDownLabel);
    if (s.volValue) v[11] = lgfxsb::Value::text(s.volValue);
    v[14].visible = s.volUpPressedVisible.v;
    if (s.volUpLabel) v[15] = lgfxsb::Value::text(s.volUpLabel);
    if (s.briLabel) v[16] = lgfxsb::Value::text(s.briLabel);
    v[19].visible = s.briDownPressedVisible.v;
    if (s.briDownLabel) v[20] = lgfxsb::Value::text(s.briDownLabel);
    if (s.briValue) v[21] = lgfxsb::Value::text(s.briValue);
    v[24].visible = s.briUpPressedVisible.v;
    if (s.briUpLabel) v[25] = lgfxsb::Value::text(s.briUpLabel);
    if (s.monitor) v[27] = lgfxsb::Value::text(s.monitor);
    v[30].visible = s.creditBtnPressedVisible.v;
    if (s.creditBtnLabel) v[31] = lgfxsb::Value::text(s.creditBtnLabel);
    renderScene(Scene::Settings::id, v, 32, _ov_Settings ? &_ovt_Settings : nullptr, &s, &_ov_Settings);
  }
  void setOverlay(void (*fn)(Canvas&, const Scene::Settings&)) { _ov_Settings = fn; }
  Scene::Settings::Part hitTest(const Scene::Settings& s, int32_t x, int32_t y) {
    static const uint16_t t[] = {2, 8, 13, 18, 23, 29};
    lgfxsb::Value v[32];
    v[3].visible = s.backBtnPressedVisible.v;
    v[9].visible = s.volDownPressedVisible.v;
    v[14].visible = s.volUpPressedVisible.v;
    v[19].visible = s.briDownPressedVisible.v;
    v[24].visible = s.briUpPressedVisible.v;
    v[30].visible = s.creditBtnPressedVisible.v;
    return static_cast<Scene::Settings::Part>(hitTestScene(Scene::Settings::id, v, 32, t, 6, x, y));
  }
  bool bounds(Scene::Settings::Part p, lgfxsb::Rect& out) { return partBounds(Scene::Settings::id, static_cast<uint16_t>(p), out); }
  void show(const Scene::Message& s) {
    lgfxsb::Value v[8];
    if (s.msg) v[3] = lgfxsb::Value::text(s.msg);
    v[6].visible = s.okBtnPressedVisible.v;
    if (s.okBtnLabel) v[7] = lgfxsb::Value::text(s.okBtnLabel);
    renderScene(Scene::Message::id, v, 8, _ov_Message ? &_ovt_Message : nullptr, &s, &_ov_Message);
  }
  void setOverlay(void (*fn)(Canvas&, const Scene::Message&)) { _ov_Message = fn; }
  Scene::Message::Part hitTest(const Scene::Message& s, int32_t x, int32_t y) {
    static const uint16_t t[] = {5};
    lgfxsb::Value v[8];
    v[6].visible = s.okBtnPressedVisible.v;
    return static_cast<Scene::Message::Part>(hitTestScene(Scene::Message::id, v, 8, t, 1, x, y));
  }
  bool bounds(Scene::Message::Part p, lgfxsb::Rect& out) { return partBounds(Scene::Message::id, static_cast<uint16_t>(p), out); }
};

